from dataclasses import dataclass

STATUSES = ("placed", "paid", "shipped", "delivered")


@dataclass
class Order:
    status: str = "placed"


def advance(order, status):
    """Move the order exactly one step forward; irreversible."""
    if status not in STATUSES:
        raise ValueError(f"unknown status: {status}")
    if STATUSES.index(status) != STATUSES.index(order.status) + 1:
        raise ValueError(f"cannot move from {order.status} to {status}")
    order.status = status
